31	func screen(a *App) []string { return strings.Split(ansi.Strip(a.View()), "\n") }
32	
33	// filetIndex returns the line of the list's bottom rule, or -1.
34	func filetIndex(lines []string) int {
35		for i, l := range lines {
36			if strings.HasPrefix(l, "├─") {
37				return i
38			}
39		}
40		return -1
41	}
42	
43	// listRows returns the list rows (between the title line and the rule).
44	func listRows(t *testing.T, a *App) []string {
45		t.Helper()
46		lines := screen(a)
47		end := filetIndex(lines)
48		if end < 0 {
49			t.Fatalf("no list rule on screen:\n%s", strings.Join(lines, "\n"))
50		}
51		start := -1
52		for i, l := range lines[:end] {
53			if strings.HasPrefix(l, "┌") {
54				start = i
55			}
56		}
57		if start < 0 {
58			t.Fatalf("no title line above the list:\n%s", strings.Join(lines, "\n"))
59		}
60		return lines[start+1 : end]
61	}
62	
63	// filet returns the text of the bottom rule.
64	func filet(t *testing.T, a *App) string {
65		t.Helper()
66		lines := screen(a)
67		i := filetIndex(lines)
68		if i < 0 {
69			t.Fatalf("no list rule on screen:\n%s", strings.Join(lines, "\n"))
70		}
71		return lines[i]
72	}
