358	// assertNoTimer fails when the Cmd blocks, which is what tea.Tick does.
359	func assertNoTimer(t *testing.T, cmd tea.Cmd) {
360		t.Helper()
361		if cmd == nil {
362			return
363		}
364		done := make(chan struct{})
365		go func() { cmd(); close(done) }()
366		select {
367		case <-done:
368		case <-time.After(300 * time.Millisecond):
369			t.Error("the warning started a timer; it must last until the next keystroke")
370		}
371	}
