		Total:   a.suggestions.Total,
		Query:   a.suggestions.Query,
		Cursor:  a.sugCursor,
		Offset:  a.sugOffset,
		Notice:  a.sugNotice,
		Width:   a.viewport.Width,
		Visible: visible,
		Frame:   frame,
	})
}

